"""Turn results/ into docs/RESULTS.md (tables + auto-generated findings) and copy charts into docs/.
Usage: python -m src.summarize
"""
import shutil
from pathlib import Path
import numpy as np
import pandas as pd

R, D = Path("results"), Path("docs")


def md(df, nd=3):
    df = df.reset_index()
    head = "| " + " | ".join(map(str, df.columns)) + " |\n|" + "---|" * len(df.columns) + "\n"
    def f(v):
        if isinstance(v, (float, np.floating)):
            return "" if np.isnan(v) else f"{v:.{nd}f}"
        return str(v)
    return head + "\n".join("| " + " | ".join(f(v) for v in row) + " |" for row in df.itertuples(index=False)) + "\n"


def _cmp(v, good, bad=None):
    return f"{abs(v):.1f}% {good}" if v >= 0 else f"{abs(v):.1f}% {bad or 'worse'}"


def main():
    D.mkdir(exist_ok=True)
    fm = pd.read_csv(R / "forecast_metrics.csv", index_col=0)
    hc = pd.read_csv(R / "headline_cost_at_target_fill_rate.csv", index_col=0)
    sens = pd.read_csv(R / "sensitivity.csv", index_col=0)
    cc = pd.read_csv(R / "conformal_check.csv", index_col=0) if (R / "conformal_check.csv").exists() else None
    shap = pd.read_csv(R / "shap_importance.csv", index_col=0)

    F = []   # auto findings
    best = fm["wrmsse"].idxmin()
    F.append(f"- Best point accuracy (WRMSSE): **{best}** ({fm.loc[best, 'wrmsse']:.3f}) vs {fm.loc['ma28', 'wrmsse']:.3f} "
             f"for the 28-day moving average ({_cmp(100 * (1 - fm.loc[best, 'wrmsse'] / fm.loc['ma28', 'wrmsse']), 'lower error')}).")
    sp = fm["spl"].dropna()
    if len(sp) > 1:
        F.append(f"- Best probabilistic accuracy (scaled pinball loss): **{sp.idxmin()}** ({sp.min():.3f}); "
                 f"the empirical-quantile baseline scores {fm.loc['empirical_q', 'spl']:.3f}.")
        F.append(f"- Raw P10-P90 interval coverage of the LightGBM quantile model: {fm.loc['lgb_quantile', 'coverage_10_90']:.1%} (target 80%).")
    if cc is not None and {"raw", "conformal"} <= set(cc.index):
        F.append(f"- Conformal calibration moved coverage from {cc.loc['raw', 'coverage_10_90']:.1%} to "
                 f"{cc.loc['conformal', 'coverage_10_90']:.1%} and changed mean interval width from "
                 f"{cc.loc['raw', 'mean_width_10_90']:.2f} to {cc.loc['conformal', 'mean_width_10_90']:.2f} units.")
        if abs(cc.loc['raw', 'coverage_10_90'] - cc.loc['conformal', 'coverage_10_90']) < 0.002:
            F.append("  - No correction was applied: intervals already over-cover, and with zero-heavy demand most "
                     "conformity scores are exactly 0, so the correction is 0. Conformal here only widens bands "
                     "that under-cover; say this plainly instead of claiming an improvement.")
    h = hc.drop(index=[i for i in hc.index if i.startswith("oracle")], errors="ignore")
    b = h["cost_at_target"].idxmin()
    F.append(f"- Cheapest realistic inventory policy at the target fill rate: **{b}**, "
             f"{_cmp(h.loc[b, 'saving_vs_ma28_%'], 'cheaper', 'more expensive')} than the moving-average policy.")
    for col in ["lgb_quantile+MC", "lgb_tweedie+normal_SS"]:
        if col in sens.columns:
            lo, hi = sens[col].min(), sens[col].max()
            verdict = "positive in every scenario" if lo > 0 else "NOT consistently positive"
            F.append(f"- Across {len(sens)} cost scenarios, the saving of **{col}** ranges {lo:+.1f}% to {hi:+.1f}% ({verdict}).")
    if h.loc[b, "saving_vs_ma28_%"] < 2:
        F.append("- **Caution:** the best saving is under 2%; say plainly that the gain over a simple policy is modest.")
    F.append(f"- Top SHAP drivers of predicted demand: {', '.join(shap.index[:5])}.")

    for img in ["forecast_examples", "cost_vs_service", "feature_importance", "shap_importance", "sensitivity"]:
        if (R / f"{img}.png").exists():
            shutil.copy(R / f"{img}.png", D / f"{img}.png")

    txt = "# Results (auto-generated by `python -m src.summarize`)\n\n## Key findings\n" + "\n".join(F) + "\n\n"
    txt += "## Forecast accuracy (mean over backtest folds)\n" + md(fm) + "\n"
    if cc is not None:
        txt += "## Interval calibration: raw vs conformal (folds 2..K)\n" + md(cc) + "\n"
    txt += "## Inventory cost at the target fill rate (simulated $)\n" + md(hc, 2) + "\n"
    txt += "## Sensitivity: % cost saving vs moving-average policy under different cost assumptions\n" + md(sens, 1) + "\n"
    txt += "![forecasts](forecast_examples.png)\n\n![cost vs service](cost_vs_service.png)\n\n"
    txt += "![sensitivity](sensitivity.png)\n\n![shap](shap_importance.png)\n\n![gain](feature_importance.png)\n"
    (D / "RESULTS.md").write_text(txt)
    print(txt)


if __name__ == "__main__":
    main()
